# Check match_func_clean for issues
import ast
try:
    ast.parse(match_func_clean)
    print("match_func_clean AST OK")
except SyntaxError as e:
    print(f"match_func_clean SyntaxError at line {e.lineno}: {e.msg}")
    lines = match_func_clean.split('\n')
    start = max(0, e.lineno - 5)
    end = min(len(lines), e.lineno + 5)
    for i in range(start, end):
        marker = ">>>" if i == e.lineno - 1 else "   "
        print(f"{marker} {i+1}: {lines[i]}")
